"""Check malformed image rejection and generated byte/CRC preservation."""
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
import zlib

SCRIPT = Path(__file__).resolve().parents[1] / "scripts/embed_rom.py"

class EmbedTests(unittest.TestCase):
    def test_pattern(self):
        with tempfile.TemporaryDirectory() as tmp:
            header = Path(tmp) / "rom.h"
            subprocess.run([sys.executable, SCRIPT, header], check=True)
            self.assertIn("0x12,0x34,0xa5,0x5a", header.read_text())

    def test_rom_and_errors(self):
        with tempfile.TemporaryDirectory() as tmp:
            header, rom = Path(tmp) / "rom.h", Path(tmp) / "image.rom"
            data = bytearray(range(256))
            data[8:12] = bytes.fromhex("feedbeef")
            rom.write_bytes(data)
            subprocess.run([sys.executable, SCRIPT, header, "--rom", rom], check=True)
            self.assertIn(f"0x{zlib.crc32(data):08x}", header.read_text())
            for invalid in (b"", b"x", bytes(256), data + b"x", bytes(65538)):
                rom.write_bytes(invalid)
                result = subprocess.run([sys.executable, SCRIPT, header, "--rom", rom],
                                        capture_output=True)
                self.assertNotEqual(result.returncode, 0)

if __name__ == "__main__":
    unittest.main()
